use boreas_tun::*;
use std::{net::{IpAddr,Ipv4Addr},time::{Duration,Instant}};
fn v4(ttl:u8,flags:u16,payload:&[u8])->Vec<u8>{let mut p=vec![0u8;20+payload.len()];p[0]=0x45;let n=p.len() as u16;p[2..4].copy_from_slice(&n.to_be_bytes());p[4..6].copy_from_slice(&0x1234u16.to_be_bytes());p[6..8].copy_from_slice(&flags.to_be_bytes());p[8]=ttl;p[9]=17;p[12..16].copy_from_slice(&[10,0,0,1]);p[16..20].copy_from_slice(&[10,0,0,2]);p[20..].copy_from_slice(payload);let c=cs(&p[..20]);p[10..12].copy_from_slice(&c.to_be_bytes());p}
fn cs(d:&[u8])->u16{let mut s=0u32;for c in d.chunks(2){s+=if c.len()==2{u16::from_be_bytes([c[0],c[1]])as u32}else{(c[0]as u32)<<8}}while s>>16!=0{s=(s&0xffff)+(s>>16)}!(s as u16)}
fn v6(ext:usize)->Vec<u8>{let mut p=vec![0u8;40+ext*8+8];p[0]=0x60;p[4..6].copy_from_slice(&((ext*8+8)as u16).to_be_bytes());p[6]=if ext>0{60}else{17};p[7]=32;p[8]=0x20;p[24]=0x20;let mut pos=40;for i in 0..ext{p[pos]=if i+1<ext{60}else{17};p[pos+1]=0;pos+=8;}p}
#[test]fn ipv4_strict_lengths_checksum_and_decrement(){let mut p=v4(4,0,b"payload");assert_eq!(inspect_packet(&p).unwrap().packet_len,p.len());decrement_hop(&mut p).unwrap();assert_eq!(p[8],3);assert_eq!(cs(&p[..20]),0);let mut bad=v4(5,0,b"");bad[10]^=1;assert_eq!(inspect_packet(&bad),Err(Error::InvalidChecksum));let mut bad=v4(5,0,b"");bad[3]+=1;assert_eq!(inspect_packet(&bad),Err(Error::InvalidLength));assert_eq!(decrement_hop(&mut v4(1,0,b"")),Err(Error::TtlExpired));}
#[test]fn ipv6_extension_depth_limit(){assert_eq!(inspect_packet(&v6(4)).unwrap().protocol,17);assert_eq!(inspect_packet(&v6(5)),Err(Error::TooManyExtensions));let mut p=v6(0);p[7]=1;assert_eq!(decrement_hop(&mut p),Err(Error::TtlExpired));}
#[test]fn pmtu_df_and_ipv6(){let p=v4(10,0x4000,&[0;60]);assert_eq!(pmtu_action(&p,40),Err(Error::InvalidLength));assert_eq!(pmtu_action(&p,68),Ok(MtuAction::Ipv4FragmentationNeeded));let p=v4(10,0,&[0;80]);assert_eq!(pmtu_action(&p,68),Ok(MtuAction::Ipv4Fragment));let mut big6=v6(0);big6.extend_from_slice(&[0;1300]);let plen=(big6.len()-40) as u16;big6[4..6].copy_from_slice(&plen.to_be_bytes());assert_eq!(pmtu_action(&big6,1280),Ok(MtuAction::Ipv6PacketTooBig));}
#[test]fn virtual_tun_capacity_and_packet_io(){let(a,b)=VirtualTun::pair(1,1,1500);let p=v4(64,0,b"");a.inject(&p).unwrap();assert_eq!(a.inject(&p),Err(Error::QueueFull));assert_eq!(a.read_packet().unwrap(),Some(p.clone()));a.write_packet(&p).unwrap();assert_eq!(b.read_packet().unwrap(),Some(p));}
#[test]fn virtio_bounds_and_gso_fail_closed(){let p=v4(64,0,b"");assert_eq!(parse_virtio_frame(&[0;9],OffloadCaps::default()),Err(Error::VirtioHeaderTruncated));let mut f=vec![0;VNET_HDR_LEN];f.extend_from_slice(&p);assert!(parse_virtio_frame(&f,OffloadCaps::default()).is_ok());f[1]=1;f[2]=20;f[4]=1;assert_eq!(parse_virtio_frame(&f,OffloadCaps{tso4:true,..Default::default()}),Err(Error::VirtioUnsupportedGso));}
#[test]fn fragment_tracker_bounds_overlap_expiry_and_key_dimensions(){let now=Instant::now();let limits=FragmentLimits{streams:1,per_stream_bytes:32,global_bytes:32,timeout:Duration::from_secs(5)};let mut t=FragmentTracker::new(limits);let k=FragmentKey{src:IpAddr::V4(Ipv4Addr::LOCALHOST),dst:IpAddr::V4(Ipv4Addr::new(10,0,0,1)),protocol:17,identification:1};t.observe(k,0,8,true,now).unwrap();assert_eq!(t.observe(k,0,8,true,now),Err(Error::FragmentOverlap));assert_eq!(t.tracked_streams(),0);assert_eq!(t.observe(k,0,8,true,now),Err(Error::FragmentTimeout));let k2=FragmentKey{identification:2,..k};t.observe(k2,0,8,true,now).unwrap();let k3=FragmentKey{identification:3,..k};assert_eq!(t.observe(k3,0,8,true,now+Duration::from_secs(1)),Err(Error::FragmentLimit));assert_eq!(t.expire(now+Duration::from_secs(5)),1);assert_eq!(t.buffered_bytes(),0);}
